  keypoint:'キーワードは「既存サーバーをコード変更なし」「ブロックレベルで継続レプリケーション」「RPO秒〜分・RTO数分」「普段は最小リソースでステージング」。DR専用のマネージドサービスを選ぶ。',
  explain:'AWS Elastic Disaster Recovery(AWS DRS)はオンプレ/EC2のソースをブロックレベルで継続レプリケーションし、平常時は低コストのステージング領域で待機、障害時に本番スペックのインスタンスを起動する。RPO秒〜分・RTO数分のDRを既存アプリ無改修で実現する専用サービス。',
  elim:'AMI定期取得はRPOが取得間隔に依存し継続レプリケーションでない。AWS Backupは日次でRPOが粗く秒〜分に届かない。MGN(Application Migration Service)は本番移行(リフト&シフト)用で継続DRでなく移行完了で役割が終わる(DRSと混同しやすい)。継続レプリケーションのDR専用＝DRS。',
  confusion:[
    {a:"AWS DRS(Elastic Disaster Recovery)",b:"MGN(Application Migration Service)",d:"DRS＝継続レプリケーションで災害復旧(平常時ステージング・障害時起動)を繰り返し使う。MGN＝一度きりの移行(リフト&シフト)で移行が終われば役目終了。継続DRはDRS、引っ越しはMGN。"}
  ],
  deep:`
  <div class="dh">🏷 出てきたものの「あだ名」</div>
  <div class="nick"><b>AWS DRS</b>＝「常に最新のクローンを薄く維持する影武者サービス」。本体が倒れたら影武者を本番スペックに膨らませて即起動。普段は安く待機。</div>
  <div class="dh">💡 なぜこれが正解か</div>
  「既存サーバー無改修＋ブロックレベル継続複製＋RPO秒〜分＋平常時は安く待機」はDRSの設計そのもの。MGNは引っ越し(一回)用で継続DRには使わない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>DRS＝災害復旧(継続・繰り返し)、MGN＝移行(一回)。</b>「継続レプリケーションでDR」と来たらDRS。`
