  elim:'MultiAZは同一リージョン内のAZ障害対策でリージョン障害には耐えられず、スタンバイは読み取りに使えない。同一リージョンのスナップショットはリージョン障害で一緒に失われる。RDS Proxyは接続管理でDRではない。リージョン跨ぎ＋読み取り活用＋昇格はクロスリージョンリードレプリカ。',
