  explain:'2つのVPC間だけのプライベート接続なら、VPCピアリングが最もシンプルで低コスト。ピアリングは1対1接続で、少数のVPC間接続に向く。',
  elim:'B=Transit Gatewayは多数VPCの集約に強いが、2つだけならアタッチメント等のコストと複雑さが過剰。C=インターネットゲートウェイ経由はプライベート通信でなくなる。D=PrivateLinkはサービス単位の公開向きで、VPC全体の相互通信が必要なケースには合わない。少数の相互接続はピアリング。',
  confusion:[
    {a:"VPCピアリング(少数)",b:"Transit Gateway(多数)",d:"ピアリング＝1対1・少数VPC・シンプル/低コスト(推移しない)。TGW＝多数VPC/オンプレをハブ集約・一元管理(規模が大きい時)。2つだけならピアリング、数十ならTGW。"}
  ],
  deep:`
  <div class="dh">💡 なぜこれが正解か</div>
  「2つだけ・シンプル・安く・集約予定なし」＝VPCピアリング。TGWは多数集約向けで2つには過剰、IGW経由はプライベートでない。
  <div class="dh">⚠️ つまずきやすい言葉</div>
  <b>規模で選ぶ＝少数(1対1)はピアリング、多数の集約はTransit Gateway。</b>「2つだけ」でTGWを選ぶと過剰投資。`
