  id:53, cards:["Graviton","EC2","コスト最適化"], cat:"コンピュート・高性能",
  scenario:"ある企業が、Amazon EC2やRDS、AWS Lambdaのコストを下げたいと考えています。ワークロードはオープンソースやマネージドランタイム中心で、アーキテクチャ依存の制約は少ない状態です。同等以上の性能を保ちながら価格性能比を改善してコストを下げ、移行の手間は小さく済ませることが求められています。",
