  answer:3,
  keypoint:'キーワードは「複数データソースを1回のクエリでまとめて」「必要なデータだけ(過不足なし)」「リアルタイム購読」「オフライン同期」「モバイル」。マネージドGraphQL＝AppSync。',
  explain:'AWS AppSyncはマネージドGraphQLサービスで、複数のデータソース(DynamoDB/Lambda/HTTP等)を1つのGraphQLエンドポイントに集約し、クライアントが必要なフィールドだけを1回で取得できる。リアルタイムのsubscriptionやモバイルのオフラインデータ同期にも対応する。',
