  id:63, cards:["EventBridge Scheduler","スケジューリング","サーバーレス"], cat:"アプリ統合・疎結合",
  scenario:"ある企業が、大量(数百万件規模)のスケジュールタスクを管理する必要があります。cron式やレート、特定日時の一回限りの実行をサーバーレスでスケジュールし、多様なAWSサービス(Lambda、SQS、Step Functionsなど)をターゲットに直接呼び出すことが求められています。また、スケジュールごとにタイムゾーンや再試行も設定する必要があります。",
