    "SNSのサブスクリプションにフィルターポリシーを設定し、メッセージ属性に基づいて各サブスクライバーへ必要なメッセージだけを配信する。",
    "すべてのメッセージを全サブスクライバーに一律に配信し、各サブスクライバー側のロジックで不要な種類のメッセージを受信後に破棄する。",
