  explain:'AWS CloudFormation StackSetsは、1つのテンプレートを複数のアカウントとリージョンへ一斉にデプロイ・更新・削除できる。Organizationsと統合すれば新規アカウントにも自動適用でき、共通基盤の横断展開・維持に最適。',
  elim:'B=各アカウント個別の手動作成は抜け漏れ・不整合が出る。C=1アカウントだけ＋他は手作業は横断展開にならない。D=メール配布＋各自実行は統制が効かず再現性もない。多数アカウント/リージョンへの一斉展開はStackSets。',
