  elim:'B=PowerUserAccessの付与は広範な権限を与えることになりガバナンス要件に反する。C=IT部門の手作業代行はセルフサービスにならずボトルネック。D=CloudWatchダッシュボードは可視化で、承認済み構成のセルフプロビジョニングではない。承認済みカタログのセルフサービスはService Catalog。',
